#include <bits/stdc++.h>
using namespace std;

using ll = long long;

void solve(){
    ll n;
    cin >> n;
    n *= 3;
    vector<ll> a(n);
    for (ll &x : a)
        cin >> x;
    sort (a.begin(), a.end());
    vector<ll> pre(n);
    pre[0] = a[0];
    for (ll i = 1; i < n; ++i)
        pre[i] = a[i] + pre[i - 1];
    auto rsum = [&](ll l, ll r){
        ll ans = pre[r];
        if (l)
            ans -= pre[l - 1];
        return ans;
    };
    ll best = 3 * pre.back();
    for (ll solo = 0, solo_sum = 0; solo <= n / 3; ++solo){
        ll l = 2 * solo;
        ll r = n - solo - 1;
        auto calc = [&](ll duo){
            ll cur = 4 * rsum(r - 2 * duo + 1, r);
            cur += 3 * rsum(l + duo, r - 2 * duo);
            return cur;
        };
        ll low = 0, high = (n - 3 * solo) / 3 + 1, last_mid = -1;
        while (low + 3 < high){
            ll mid = (low + high) / 2;
            // if(mid == last_mid){
            //     cout << solo << " " << mid << endl;
            //     break;
            // }
            // last_mid = mid;
            if (calc(mid) >= calc(mid - 1))
                low = mid;
            else
                high = mid;
        }
        for (ll i = low; i < high; ++i){
            ll cur_ans = calc(i);
            if (cur_ans > calc(low))
                low = i;
        }
        ll cur_sum = solo_sum + calc(low);
        best = max(best, cur_sum);
        solo_sum += 6 * a[r];
    }
    cout << best;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	cin >> t;
	while (t--){
	    solve();
	    cout << '\n';
	}
}
